/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
  random,
  interpolateColors,
} from '../remotionShim';
import { Star } from "@remotion/shapes";
import { makeLoadFont } from '../googleFonts';
const loadAnton = makeLoadFont('Anton');
const loadRoboto = makeLoadFont('Roboto');

// Module-level font loading — guarantees fonts are ready before frame 0
const { fontFamily: antonFamily } = loadAnton();
const { fontFamily: robotoFamily } = loadRoboto();



export type JackpotPopupProps = Record<string, any>;

const JackpotPopup: React.FC<JackpotPopupProps> = ({
  backgroundColor = "#2a0000",
  transparentBackground = true,
  durationInSeconds = 5,
  jackpotText = "JACKPOT",
  winningsText = "BONUS WON!",
  accentGoldColor = "#FFD700",
  accentRedColor = "#8B0000",
  burstParticleCount = 150,
  backgroundRayCount = 24,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Safe background logic
  const finalBackground = transparentBackground
    ? "transparent"
    : `radial-gradient(circle at center, ${backgroundColor} 0%, #000000 100%)`;

  // Pre-calculate deterministic particle paths
  const particles = useMemo(() => {
    return new Array(burstParticleCount).fill(0).map((_, i) => {
      // Cube the random value to bias the delay towards 0 (creates an initial massive burst)
      const delay = Math.floor(Math.pow(random(`delay-${i}`), 3) * (fps * 2));
      const isStar = random(`star-${i}`) > 0.6;
      // Angle fanning upwards and slightly outwards
      const angle = -Math.PI / 2 + (random(`a-${i}`) - 0.5) * Math.PI * 0.9;
      // Proportional force based on canvas height
      const force = random(`f-${i}`) * (height * 0.045) + height * 0.02;
      const rotSpeed = random(`rot-${i}`) * 20 - 10;
      // Responsive sizes
      const size = random(`size-${i}`) * (width * 0.03) + width * 0.015;
      
      return { delay, isStar, angle, force, rotSpeed, size };
    });
  }, [burstParticleCount, fps, width, height]);

  const gravity = height * 0.0015;
  const rayHeight = height * 0.15;
  const rayOpacity = interpolate(Math.sin(frame * 0.1), [-1, 1], [0.15, 0.3]);
  const rays = new Array(backgroundRayCount).fill(0);

  // Text animations
  const textScaleIn = spring({
    frame,
    fps,
    config: { damping: 10, mass: 1, stiffness: 100 },
    durationInFrames: 30,
  });
  
  // Continuous pulsing effect for the main title
  const pulse = interpolate(Math.sin(frame * 0.2), [-1, 1], [0.95, 1.05]);
  const textScale = textScaleIn * pulse;
  const glowOpacity = interpolate(Math.sin(frame * 0.3), [-1, 1], [0.4, 0.8]);
  const subScale = spring({ frame: frame - 15, fps, config: { damping: 14 } });

  // High-energy flashing color interpolation
  const mainTextColor = interpolateColors(
    Math.sin(frame * 0.5),
    [-1, 1],
    [accentGoldColor, "#FFFFDD"]
  );

  return (
    <AbsoluteFill
      style={{
        background: finalBackground,
        overflow: "hidden",
        transition: "none",
      }}
    >
      {/* Rotating Background Rays Layer */}
      <AbsoluteFill style={{ justifyContent: "center", alignItems: "center" }}>
        <div
          style={{
            position: "absolute",
            left: "50%",
            top: "50%",
            width: 0,
            height: 0,
            transform: `rotate(${frame * 0.5}deg)`,
            transition: "none",
          }}
        >
          {rays.map((_, i) => (
            <div
              key={`ray-${i}`}
              style={{
                position: "absolute",
                width: width * 1.5,
                height: rayHeight,
                left: 0,
                top: -rayHeight / 2,
                transformOrigin: "0 50%",
                transform: `rotate(${(360 / backgroundRayCount) * i}deg)`,
                backgroundColor: accentGoldColor,
                opacity: rayOpacity,
                transition: "none",
              }}
            />
          ))}
        </div>
      </AbsoluteFill>

      {/* Particle Eruption Layer */}
      {particles.map((p, i) => {
        const time = Math.max(0, frame - p.delay);
        if (time === 0) return null;

        const scale = interpolate(time, [0, 10], [0, 1], {
          extrapolateRight: "clamp",
        });
        const vX = Math.cos(p.angle) * p.force;
        const vY = Math.sin(p.angle) * p.force;

        const x = vX * time;
        const y = vY * time + 0.5 * gravity * time * time;
        const rotation = p.rotSpeed * time;

        return (
          <div
            key={`particle-${i}`}
            style={{
              position: "absolute",
              left: width / 2,
              top: height * 0.65, // Spawn slightly below center
              transform: `translate(${x}px, ${y}px) rotate(${rotation}deg) scale(${scale})`,
              width: p.size,
              height: p.size,
              marginLeft: -p.size / 2,
              marginTop: -p.size / 2,
              transition: "none",
            }}
          >
            {p.isStar ? (
              <Star
                points={5}
                innerRadius={p.size * 0.35}
                outerRadius={p.size / 2}
                fill={accentGoldColor}
                style={{ transition: "none" }}
              />
            ) : (
              // Coin shape
              <div
                style={{
                  width: "100%",
                  height: "100%",
                  borderRadius: "50%",
                  backgroundColor: accentGoldColor,
                  border: `${Math.max(2, p.size * 0.08)}px solid ${accentRedColor}`,
                  boxSizing: "border-box",
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                  boxShadow: `inset 0 0 ${p.size * 0.2}px rgba(0,0,0,0.3)`,
                  transition: "none",
                }}
              >
                <div
                  style={{
                    width: "60%",
                    height: "60%",
                    borderRadius: "50%",
                    border: `${Math.max(1, p.size * 0.04)}px solid ${accentRedColor}`,
                    opacity: 0.8,
                    transition: "none",
                  }}
                />
              </div>
            )}
          </div>
        );
      })}

      {/* High Impact Text Layer */}
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          pointerEvents: "none",
        }}
      >
        <div
          style={{
            fontFamily: antonFamily,
            fontSize: width * 0.15,
            color: mainTextColor,
            textShadow: `0px ${height * 0.015}px 0px ${accentRedColor}, 0px 0px ${
              width * 0.04
            }px rgba(255, 215, 0, ${glowOpacity})`,
            WebkitTextStroke: `${Math.max(2, width * 0.002)}px white`,
            transform: `scale(${textScale})`,
            textAlign: "center",
            lineHeight: 1.1,
            zIndex: 10,
            textTransform: "uppercase",
            transition: "none",
          }}
        >
          {jackpotText}
        </div>
        <div
          style={{
            fontFamily: robotoFamily,
            fontSize: width * 0.04,
            color: "#FFFFFF",
            fontWeight: "bold",
            letterSpacing: width * 0.005,
            transform: `scale(${subScale})`,
            textShadow: `0px ${height * 0.005}px ${
              height * 0.01
            }px rgba(0,0,0,0.8)`,
            marginTop: height * 0.02,
            zIndex: 10,
            textTransform: "uppercase",
            WebkitTextStroke: `1px ${accentRedColor}`,
            transition: "none",
          }}
        >
          {winningsText}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default JackpotPopup;